package com.menstyle.entity;
import com.menstyle.entity.enums.*; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal;
@Getter @Setter @NoArgsConstructor @Entity @Table(name="orders",indexes={@Index(name="idx_orders_code",columnList="order_code"),@Index(name="idx_orders_user",columnList="user_id"),@Index(name="idx_orders_status",columnList="order_status"),@Index(name="idx_orders_created",columnList="created_at")},uniqueConstraints=@UniqueConstraint(name="uk_orders_code",columnNames="order_code"))
public class Order extends BaseEntity { @Column(name="order_code",nullable=false,length=50) private String orderCode; @Column(name="idempotency_key",length=100) private String idempotencyKey; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id",nullable=false) private User user; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="coupon_id") private Coupon coupon; @Column(nullable=false,precision=19,scale=2) private BigDecimal subtotal; @Column(nullable=false,precision=19,scale=2) private BigDecimal discountAmount; @Column(nullable=false,precision=19,scale=2) private BigDecimal shippingFee; @Column(nullable=false,precision=19,scale=2) private BigDecimal totalAmount; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PaymentMethod paymentMethod; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private PaymentStatus paymentStatus; @Enumerated(EnumType.STRING) @Column(name="order_status",nullable=false,length=20) private OrderStatus orderStatus; private String customerNote; private String cancellationReason; }
